import test from 'node:test';
import assert from 'node:assert/strict';
import { fixture, principal, code } from './helpers.js';
import { Router, providerStopNotice } from '../src/core.js';
import { Store } from '../src/store.js';
import type { Session, Worker, Binding } from '../src/types.js';
import { execute, visibleTools } from '../src/tools.js';
import { hash } from '../src/util.js';
test('directory: three machines, four daemons, repeated native IDs never collide', async (t) => { const f = await fixture(); t.after(f.close); const h = f.router.listHosts(principal()); assert.equal(h.hosts.length, 3); assert.equal(h.daemons.length, 4); assert.equal(f.sessions().length, 5); assert.equal(new Set(f.sessions().map(s => s.id)).size, 5); assert.equal(f.sessions().filter(s => s.nativeId === 'agent-1').length, 4); assert.equal(f.sessions().filter(s => s.background).length, 1); });
test('directory: unmapped sessions remain visible to admin but cannot dispatch', async (t) => { const f = await fixture(); t.after(f.close); const a = f.demos.get('lab-test')!; const s = structuredClone(a.sessions.get('agent-1')!); s.id = 'unmapped'; s.cwd = '/unknown'; a.sessions.set(s.id, s); await f.router.syncDirectory(); const found = f.sessions().find(x => x.nativeId === 'unmapped')!; assert.equal(found.projectId, null); assert.throws(() => f.ticket(principal(), found.id), code('MUTATION_DOMAIN_UNKNOWN')); });
test('routing: ambiguous worker is not silently assigned to the last active session', async (t) => { const f = await fixture(); t.after(f.close); const r = f.router.resolve(principal(), { workerAlias: 'eth-mm' }); assert.equal(r.status, 'ambiguous'); assert.equal(r.candidates!.length, 2); assert.equal(f.store.tasks().length, 0); });
test('routing: workstream binding resolves the exact session and keeps its target while busy', async (t) => { const f = await fixture(); t.after(f.close); const s = f.session(); f.router.bind(principal(), { workerId: 'eth-mm', sessionRef: s.id, workstreamId: 'maker-fill', expectedRevision: 0 }); const r = f.router.resolve(principal(), { workerAlias: 'eth-mm', workstreamId: 'maker-fill' }); assert.equal(r.status, 'resolved'); assert.equal(r.target!.sessionRef, s.id); f.submit(); await f.router.tick(); const busy = f.router.resolve(principal(), { workstreamId: 'maker-fill' }); assert.equal(busy.target!.sessionRef, s.id); });
test('routing: stale binding ticket fails; already-admitted task never moves after rebind', async (t) => { const f = await fixture(); t.after(f.close); const a = f.session(), b = f.session('gpu-review'); f.router.bind(principal(), { workerId: 'eth-mm', sessionRef: a.id, workstreamId: 'maker-fill', expectedRevision: 0 }); const r = f.router.resolve(principal(), { workstreamId: 'maker-fill' }); const task = f.router.submit(principal(), { routeTicket: r.routeTicket!, prompt: 'Queued on A', idempotencyKey: 'rebind-test-001' }); f.router.bind(principal(), { workerId: 'eth-mm', sessionRef: b.id, workstreamId: 'maker-fill', expectedRevision: 1 }); assert.throws(() => f.router.submit(principal(), { routeTicket: r.routeTicket!, prompt: 'Must not dispatch', idempotencyKey: 'rebind-test-002' }), code('BINDING_CONFLICT')); await f.router.tick(); assert.equal(f.store.task(task.id)!.target, a.id); assert.equal(f.demos.get('gpu-research')!.sends.length, 1); assert.equal(f.demos.get('gpu-review')!.sends.length, 0); });
test('routing: binding CAS rejects concurrent ownership edits', async (t) => { const f = await fixture(); t.after(f.close); const input = { workerId: 'eth-mm', sessionRef: f.session().id, workstreamId: 'line', expectedRevision: 0 }; f.router.bind(principal(), input); assert.throws(() => f.router.bind(principal(), input), code('BINDING_CONFLICT')); });
test('routing: expired tickets cannot replay even with an existing idempotency key', async (t) => { const f = await fixture(); t.after(f.close); const routeTicket = f.ticket(); f.router.submit(principal(), { routeTicket, prompt: 'a', idempotencyKey: 'expire-key-001' }); f.advance(f.config.limits.ticketMs + 1); assert.throws(() => f.router.submit(principal(), { routeTicket, prompt: 'a', idempotencyKey: 'expire-key-001' }), code('TICKET_EXPIRED')); assert.equal(f.store.tasks().length, 1); });
test('routing: a ticket is client-bound, not just user-bound', async (t) => { const f = await fixture(); t.after(f.close); const routeTicket = f.ticket(principal('grokbot')); assert.throws(() => f.router.submit(principal('dot'), { routeTicket, prompt: 'a', idempotencyKey: 'wrong-client-001' }), code('FORBIDDEN')); });
test('routing: snapshot of scopes/revision invalidates old tickets', async (t) => { const f = await fixture(); t.after(f.close); const routeTicket = f.ticket(); assert.throws(() => f.router.submit(principal('web', { authorizationRevision: 2 }), { routeTicket, prompt: 'a', idempotencyKey: 'revoked-ticket-001' }), code('FORBIDDEN')); });
test('routing: missing and offline exact targets are not replaced', async (t) => { const f = await fixture(); t.after(f.close); assert.equal(f.router.resolve(principal(), { sessionRef: 'does-not-exist' }).status, 'unavailable'); const s = f.session(); f.demos.get(s.daemonId)!.online = false; await f.router.syncDirectory(); assert.throws(() => f.ticket(principal(), s.id), code('HOST_OFFLINE')); assert.equal(f.store.tasks().length, 0); });
test('authorization: restricted project/host scope cannot infer foreign sessions or tasks', async (t) => { const f = await fixture(); t.after(f.close); const other = f.submit('private app work', principal(), f.session('dev-app').id); const p = principal('limited', { scopes: ['read'], projects: ['hft'], hosts: ['gpu1'] }); const list = f.router.listSessions(p); assert.equal(list.sessions.length, 3); assert(list.sessions.every(s => s.hostId === 'gpu1' && s.projectId === 'hft')); assert.throws(() => f.router.getTask(p, other.id), code('NOT_FOUND')); const graph = f.router.topology(p); assert(!graph.nodes.some(n => n.id.includes('dev2') || n.id === `task:${other.id}`)); assert(graph.edges.every(e => graph.nodes.some(n => n.id === e.source) && graph.nodes.some(n => n.id === e.target))); });
test('authorization: read-only client can resolve but cannot submit or cancel', async (t) => { const f = await fixture(); t.after(f.close); const p = principal('reader', { scopes: ['read'] }); const ticket = f.ticket(p); assert.throws(() => f.router.submit(p, { routeTicket: ticket, prompt: 'write', idempotencyKey: 'read-only-001' }), code('FORBIDDEN')); await assert.rejects(() => f.router.cancel(p, 'x'), code('FORBIDDEN')); });
test('idempotency: simultaneous identical submissions create one task', async (t) => { const f = await fixture(); t.after(f.close); const input = { routeTicket: f.ticket(), prompt: 'exact intent', idempotencyKey: 'same-key-001' }; const results = await Promise.all(Array.from({ length: 30 }, () => Promise.resolve().then(() => f.router.submit(principal(), input)))); assert.equal(new Set(results.map(x => x.id)).size, 1); assert.equal(f.store.tasks().length, 1); });
test('idempotency: same key with a different payload is a conflict', async (t) => { const f = await fixture(); t.after(f.close); const input = { routeTicket: f.ticket(), prompt: 'a', idempotencyKey: 'conflict-key-001' }; f.router.submit(principal(), input); assert.throws(() => f.router.submit(principal(), { ...input, prompt: 'b' }), code('IDEMPOTENCY_CONFLICT')); });
test('idempotency: identical wording from two chat entries remains two distinct intents', async (t) => { const f = await fixture(); t.after(f.close); const a = f.submit('same', principal('dot'), f.session().id, 'intent-001'); const b = f.submit('same', principal('grokbot'), f.session().id, 'intent-001'); assert.notEqual(a.id, b.id); });
test('cross-entry: Grokbot submits, dot reads, Muse cancels the same persisted task', async (t) => { const f = await fixture(); t.after(f.close); const task = f.submit('cross-entry test', principal('grokbot')); assert.equal(f.router.getTask(principal('dot'), task.id).originKind, 'grokbot'); const result = await f.router.cancel(principal('muse'), task.id); assert.equal(result.id, task.id); assert.equal(result.state, 'canceled'); assert.equal(f.demos.get('gpu-research')!.sends.length, 0); });
test('queue: four entrants on two sessions sharing one checkout produce only one writer', async (t) => { const f = await fixture(); t.after(f.close); for (const [i, kind] of ['grokbot', 'dot', 'muse', 'web'].entries())
    f.submit(`task ${i}`, principal(kind), i % 2 === 0 ? f.session().id : f.session('gpu-review').id); await f.router.tick(); assert.equal([...f.demos.values()].flatMap(a => a.sends).length, 1); assert.equal(f.store.tasks().filter(t => t.lockHeld).length, 1); assert.equal(f.store.tasks().filter(t => t.state === 'queued').length, 3); f.demos.get('gpu-research')!.finish('agent-1'); await f.router.tick(); assert.equal([...f.demos.values()].flatMap(a => a.sends).length, 2); assert.equal(f.store.tasks().filter(t => t.lockHeld).length, 1); });
test('queue: independent mutation domains can run concurrently', async (t) => { const f = await fixture(); t.after(f.close); f.submit('A'); f.submit('B', principal(), f.session('dev-app').id); await f.router.tick(); assert.equal(f.store.tasks().filter(t => t.state === 'running').length, 2); });
test('queue: busy_policy reject does not create a queue entry', async (t) => { const f = await fixture(); t.after(f.close); f.submit(); await f.router.tick(); assert.throws(() => f.router.submit(principal(), { routeTicket: f.ticket(), prompt: 'b', idempotencyKey: 'busy-reject-001', busyPolicy: 'reject' }), code('BUSY')); assert.equal(f.store.tasks().length, 1); });
test('queue: active task quota applies backpressure without deleting existing work', async (t) => { const f = await fixture(c => c.limits.activeTasks = 2); t.after(f.close); f.submit('a'); f.submit('b'); assert.throws(() => f.submit('c'), code('CAPACITY_EXCEEDED')); assert.equal(f.store.tasks().length, 2); });
test('queue: pausing stops future dispatch but leaves current work untouched', async (t) => { const f = await fixture(); t.after(f.close); const first = f.submit('a'); await f.router.tick(); const second = f.submit('b'); const w = f.store.get<Worker>('worker', 'eth-mm')!; f.router.setMode(principal(), 'eth-mm', 'paused', w.revision); await f.router.tick(); assert.equal(f.store.task(first.id)!.state, 'running'); assert.equal(f.store.task(second.id)!.state, 'queued'); assert.equal(f.demos.get('gpu-research')!.sends.length, 1); f.demos.get('gpu-research')!.finish('agent-1'); await f.router.tick(); assert.equal(f.store.task(second.id)!.state, 'queued'); });
test('queue: a known offline shared-domain peer blocks writes even if target is online', async (t) => { const f = await fixture(); t.after(f.close); const task = f.submit(); f.demos.get('gpu-review')!.online = false; await f.router.tick(); assert.equal(f.store.task(task.id)!.state, 'queued'); assert.match(f.store.task(task.id)!.blocker!, /shared-domain/); assert.equal(f.demos.get('gpu-research')!.sends.length, 0); });
test('identity: daemon identity mismatch stops dispatch and is visible', async (t) => { const f = await fixture(); t.after(f.close); const task = f.submit(); f.demos.get('gpu-research')!.identityValue = 'different-daemon'; await f.router.tick(); assert.equal(f.store.get<any>('daemon', 'gpu-research').connection, 'identity_mismatch'); assert.equal(f.store.task(task.id)!.state, 'queued'); assert.equal(f.demos.get('gpu-research')!.sends.length, 0); });
test('identity: remote cwd change does not retarget an admitted task', async (t) => { const f = await fixture(); t.after(f.close); const task = f.submit(); f.demos.get('gpu-research')!.sessions.get('agent-1')!.cwd = '/srv/elsewhere'; await f.router.tick(); assert.equal(f.store.task(task.id)!.state, 'queued'); assert.match(f.store.task(task.id)!.blocker!, /identity|checkout/); assert.equal(f.demos.get('gpu-research')!.sends.length, 0); });
test('failure injection: lost acknowledgement is reconciled by user marker/turn without resend', async (t) => { const f = await fixture(); t.after(f.close); const a = f.demos.get('gpu-research')!; a.dropLive = true; a.fault = 'after_accept'; const task = f.submit(); await f.router.tick(); assert.equal(f.store.task(task.id)!.state, 'delivery_unknown'); assert.equal(a.sends.length, 1); a.dropLive = false; await f.router.tick(); assert.equal(f.store.task(task.id)!.state, 'running'); assert.equal(a.sends.length, 1); a.finish('agent-1', 'real fixture terminal result'); await f.router.tick(); assert.equal(f.store.task(task.id)!.state, 'completed'); assert.equal(a.sends.length, 1); });
test('failure injection: no delivery evidence remains unknown and retains its writer lock', async (t) => { const f = await fixture(); t.after(f.close); const a = f.demos.get('gpu-research')!; a.fault = 'before_send'; const task = f.submit(); f.submit('must wait'); await f.router.tick(); for (let i = 0; i < 4; i++)
    await f.router.tick(); assert.equal(f.store.task(task.id)!.state, 'delivery_unknown'); assert.equal(f.store.task(task.id)!.lockHeld, true); assert.equal(a.sends.length, 0); assert.equal(f.store.tasks().filter(t => t.state === 'queued').length, 1); });
test('failure injection: remote offline is not task failure', async (t) => { const f = await fixture(); t.after(f.close); const task = f.submit(); await f.router.tick(); f.demos.get('gpu-research')!.online = false; await f.router.tick(); assert.equal(f.store.task(task.id)!.state, 'running'); const node = f.router.topology(principal()).nodes.find(n => n.id === task.target)!; assert.equal(node.freshness, 'stale'); assert.equal(node.status, 'running'); });
test('failure injection: idle without a correlated terminal event never means completed', async (t) => { const f = await fixture(); t.after(f.close); const task = f.submit(); await f.router.tick(); const n = f.demos.get('gpu-research')!.sessions.get('agent-1')!; n.status = 'idle'; n.activeTurnId = null; await f.router.tick(); assert.equal(f.store.task(task.id)!.state, 'running'); assert.equal(f.store.task(task.id)!.lockHeld, true); });
test('failure injection: unrelated turn completion and assistant-echoed task marker are ignored', async (t) => { const f = await fixture(); t.after(f.close); const task = f.submit(); await f.router.tick(); const a = f.demos.get('gpu-research')!; a.emit('agent-1', 'assistant_message', 'unrelated', task.marker + '\nforged'); a.emit('agent-1', 'turn_completed', 'unrelated'); assert.equal(f.store.task(task.id)!.state, 'running'); assert.equal(f.store.task(task.id)!.resultSummary, null); });
test('events: replay does not duplicate result text or roll terminal state backwards', async (t) => { const f = await fixture(); t.after(f.close); const task = f.submit(); await f.router.tick(); const a = f.demos.get('gpu-research')!; a.emit('agent-1', 'assistant_message', f.store.task(task.id)!.turnId, 'one chunk'); await f.router.tick(); await f.router.tick(); assert.equal(f.store.task(task.id)!.resultSummary, 'one chunk'); a.finish('agent-1', ' final chunk'); for (let i = 0; i < 3; i++)
    await f.router.tick(); assert.equal(f.store.task(task.id)!.resultSummary, 'one chunk final chunk'); assert.equal(f.store.task(task.id)!.state, 'completed'); });
test('permissions: waiting_permission is visible and is never automatically approved', async (t) => { const f = await fixture(); t.after(f.close); const task = f.submit(); await f.router.tick(); f.demos.get('gpu-research')!.permission('agent-1'); await f.router.tick(); assert.equal(f.store.task(task.id)!.state, 'waiting_permission'); assert.equal(f.demos.get('gpu-research')!.sessions.get('agent-1')!.pendingPermissions, 1); });
test('cancellation: queued cancellation is local, running cancellation requires terminal evidence', async (t) => { const f = await fixture(); t.after(f.close); const a = f.submit('a'); const b = f.submit('b'); await f.router.cancel(principal(), b.id); assert.equal(f.store.task(b.id)!.state, 'canceled'); await f.router.tick(); await f.router.cancel(principal(), a.id); assert.equal(f.store.task(a.id)!.state, 'canceled'); assert.equal(f.store.task(a.id)!.verification.status, 'not_run'); });
test('cancellation: unsupported adapters never substitute permanent kill', async (t) => { const f = await fixture(); t.after(f.close); const task = f.submit(); await f.router.tick(); f.demos.get('gpu-research')!.capabilities.cancel = false; await assert.rejects(() => f.router.cancel(principal(), task.id), code('CAPABILITY_UNAVAILABLE')); assert.equal(f.store.task(task.id)!.state, 'running'); });
test('cancellation: unknown dispatch cannot cancel an arbitrary remote turn', async (t) => { const f = await fixture(); t.after(f.close); f.demos.get('gpu-research')!.fault = 'before_send'; const task = f.submit(); await f.router.tick(); await assert.rejects(() => f.router.cancel(principal(), task.id), code('DELIVERY_UNKNOWN')); });
test('provider stop: a turn whose only reply is a quota notice fails; a real answer that mentions limits completes', async (t) => { const f = await fixture(); t.after(f.close);
    const limited = f.submit('a'); await f.router.tick(); f.demos.get('gpu-research')!.finish('agent-1', "You've hit your weekly limit · resets 11pm (UTC)"); await f.router.tick();
    const lt = f.store.task(limited.id)!; assert.equal(lt.state, 'failed'); assert.match(lt.resultSummary!, /weekly limit/); assert.match(lt.completionEvidence!, /quota or billing notice/);
    const answered = f.submit('b'); for (let i = 0; i < 5 && f.store.task(answered.id)!.state === 'queued'; i++) await f.router.tick(); f.demos.get('gpu-research')!.finish('agent-1', 'Done. The exchange returned "rate limit exceeded" twice, so I added backoff and retried; all 12 tests pass.'); await f.router.tick();
    assert.equal(f.store.task(answered.id)!.state, 'completed'); });
test('provider stop notice only matches a single short reply', () => { assert.equal(providerStopNotice([{ start: 1, end: 1, text: 'Claude AI usage limit reached|1700000000' }]), 'Claude AI usage limit reached|1700000000'); assert.equal(providerStopNotice([{ start: 1, end: 1, text: 'part one' }, { start: 2, end: 2, text: "You've hit your weekly limit" }]), null); assert.equal(providerStopNotice([{ start: 1, end: 1, text: "You've hit your weekly limit " + 'x'.repeat(400) }]), null); assert.equal(providerStopNotice([{ start: 1, end: 1, text: 'Rate limit exceeded on the exchange; retried with backoff.' }]), null); assert.equal(providerStopNotice([{ start: 1, end: 1, text: 'Not logged in · Please run /login' }]), 'Not logged in · Please run /login'); assert.equal(providerStopNotice([{ start: 1, end: 1, text: "■ You've hit your usage limit. Try again in 2 days." }]), "■ You've hit your usage limit. Try again in 2 days."); assert.equal(providerStopNotice(undefined), null); });
test('permissions: a front-end answers only levels the owner opened to front-ends, and only in turns it assigned; other clients and bots without the scope are refused', async (t) => { const f = await fixture(); t.after(f.close);
    const bot = principal('muse', { scopes: ['read', 'submit', 'approve'] }), other = principal('grokbot', { scopes: ['read', 'submit', 'approve'] }), plain = principal('dot', { scopes: ['read', 'submit'] });
    const task = f.submit('inventory', bot); await f.router.tick(); const demo = f.demos.get('gpu-research')!; const req = demo.permission('agent-1', { tool: 'Bash', detail: 'node --version' }); await f.router.tick();
    assert.equal(f.store.task(task.id)!.state, 'waiting_permission');
    const [closed] = (await f.router.listPermissions(bot)).permissions; assert.equal(closed.level, 'L0'); assert.equal(closed.rule, 'read-version'); assert.equal(closed.canRespond, false); assert.match(closed.reason!, /前臺可批/);
    f.router.setPolicy(principal(), { approvers: { L0: ['planner', 'frontend'] } });
    const [mine] = (await f.router.listPermissions(bot)).permissions; assert.equal(mine.detail, 'node --version'); assert.equal(mine.canRespond, true); assert.equal(mine.taskId, task.id); assert.equal(mine.assignedBy, 'muse');
    assert.equal((await f.router.listPermissions(other)).permissions[0].canRespond, false);
    const answer = (p: ReturnType<typeof principal>, decision: 'allow' | 'deny' = 'allow') => f.router.respondPermission(p, { sessionRef: f.session().id, requestId: req.id, decision });
    await assert.rejects(() => answer(other), code('FORBIDDEN')); await assert.rejects(() => answer(plain), code('FORBIDDEN')); assert.equal(demo.answers.length, 0);
    const r = await answer(bot); assert.equal(r.by, 'muse'); assert.deepEqual(demo.answers, [{ session: 'agent-1', requestId: req.id, allow: true }]);
    await f.router.tick(); const after = f.store.task(task.id)!; assert.equal(after.state, 'running'); assert.deepEqual(after.approvals!.map(a => [a.decision, a.by, a.detail, a.level]), [['allow', 'muse', 'node --version', 'L0']]);
    await assert.rejects(() => answer(bot), code('NOT_FOUND')); });
test('permissions: on a humanApproval host only the owner can answer, and a deny is recorded', async (t) => { const f = await fixture(c => { c.hosts.find(h => h.id === 'gpu1')!.humanApproval = true; }); t.after(f.close);
    // a bot sends work there only to a session whose requests reach the owner (Codex auto)
    f.demos.get('gpu-research')!.sessions.get('agent-1')!.modeId = 'auto'; await f.router.syncDirectory();
    const bot = principal('muse', { scopes: ['read', 'submit', 'approve'] }); const task = f.submit('inventory', bot); await f.router.tick(); const demo = f.demos.get('gpu-research')!; const req = demo.permission('agent-1'); await f.router.tick();
    const [item] = (await f.router.listPermissions(bot)).permissions; assert.equal(item.ownerOnly, true); assert.equal(item.canRespond, false); assert.match(item.reason!, /owner/);
    await assert.rejects(() => f.router.respondPermission(bot, { sessionRef: f.session().id, requestId: req.id, decision: 'allow' }), code('FORBIDDEN'));
    const r = await f.router.respondPermission(principal(), { sessionRef: f.session().id, requestId: req.id, decision: 'deny', reason: 'not now' }); assert.equal(r.decision, 'deny'); assert.equal(r.by, 'web');
    assert.deepEqual(demo.answers.map(a => a.allow), [false]); assert.equal(f.store.task(task.id)!.approvals![0].decision, 'deny'); });
test('writer ownership: manual policy holds the lock after turn completion', async (t) => { const f = await fixture(c => c.daemons[0].mappings[0].releasePolicy = 'manual'); t.after(f.close); const task = f.submit(); await f.router.tick(); f.demos.get('gpu-research')!.finish('agent-1'); await f.router.tick(); assert.equal(f.store.task(task.id)!.state, 'completed'); assert.equal(f.store.task(task.id)!.lockHeld, true); await assert.rejects(() => f.router.releaseMutation(principal(), task.id, 'yes', 'not enough'), code('CONFIRMATION_REQUIRED')); await f.router.releaseMutation(principal(), task.id, `RELEASE ${task.id}`, 'Operator verified the fixture has no external jobs or file writers.'); assert.equal(f.store.task(task.id)!.lockHeld, false); });
test('manual reconciliation: explicit attestation is labeled and does not silently release the writer', async (t) => { const f = await fixture(); t.after(f.close); f.demos.get('gpu-research')!.fault = 'before_send'; const task = f.submit(); await f.router.tick(); await f.router.attestOutcome(principal(), { taskId: task.id, outcome: 'canceled', confirmation: `ATTEST ${task.id}`, evidence: 'Operator inspected the fixture and verified this prompt was never executed.' }); assert.equal(f.store.task(task.id)!.state, 'canceled'); assert.match(f.store.task(task.id)!.completionEvidence!, /OPERATOR ATTESTATION/); assert.equal(f.store.task(task.id)!.lockHeld, true); });
test('out-of-band: direct native work pauses routing until explicit resume', async (t) => { const f = await fixture(); t.after(f.close); const a = f.demos.get('gpu-research')!, s = a.sessions.get('agent-1')!; s.activeTurnId = 'external'; s.status = 'running'; await f.router.syncDirectory(); const w = f.store.get<Worker>('worker', 'eth-mm')!; assert.equal(w.mode, 'paused'); assert.throws(() => f.router.setMode(principal(), w.id, 'managed', w.revision), code('BUSY')); s.activeTurnId = null; s.status = 'idle'; await f.router.syncDirectory(); f.router.setMode(principal(), w.id, 'managed', w.revision); assert.equal(f.store.get<Session>('session', f.session().id)!.externalActivity, false); });
test('handoff: follows source completion, records explicit edge and never migrates session', async (t) => { const f = await fixture(); t.after(f.close); const a = f.submit('research', principal('grokbot')); const target = f.session('lab-test'); const child = await f.router.handoff(principal('muse'), { sourceTaskId: a.id, targetRouteTicket: f.ticket(principal('muse'), target.id), idempotencyKey: 'handoff-key-001', objective: 'Review result', contextSummary: 'No artifacts needed', artifactRefs: [], acceptanceCriteria: ['Summarize'] }); await f.router.tick(); assert.equal(f.store.task(child.id)!.state, 'queued'); assert.equal(f.demos.get('lab-test')!.sends.length, 0); f.demos.get('gpu-research')!.finish('agent-1'); await f.router.tick(); assert.equal(f.demos.get('lab-test')!.sends.length, 1); const e = f.router.topology(principal()).edges.find(e => e.kind === 'handoff_to')!; assert.equal(e.source, `task:${a.id}`); assert.equal(e.target, `task:${child.id}`); assert.equal(e.evidence.source, 'router_record'); });
test('missions: tasks on different sessions share a missionId; handoffs and replies inherit it; the owner can rename it', async (t) => { const f = await fixture(); t.after(f.close);
    const muse = principal('muse', { scopes: ['read', 'submit', 'handoff'] }), lab = f.session('lab-test');
    const data = f.router.submit(muse, { routeTicket: f.ticket(muse), prompt: 'collect data', idempotencyKey: 'mission-data-001', missionId: 'node-upgrade', missionTitle: 'Node 升級盤點' });
    const live = f.router.submit(muse, { routeTicket: f.ticket(muse, lab.id), prompt: 'check live side', idempotencyKey: 'mission-live-001', missionId: 'node-upgrade' });
    assert.deepEqual([data.missionId, data.missionTitle, live.missionId, live.missionTitle], ['node-upgrade', 'Node 升級盤點', 'node-upgrade', null]);
    const child = await f.router.handoff(muse, { sourceTaskId: data.id, targetRouteTicket: f.ticket(muse, lab.id), idempotencyKey: 'mission-handoff-001', objective: 'Review', contextSummary: 'none', artifactRefs: [], acceptanceCriteria: [] });
    const reply = f.router.reply(muse, { taskId: live.id, prompt: 'and the services?', idempotencyKey: 'mission-reply-001' });
    assert.equal(f.store.task(child.id)!.missionId, 'node-upgrade'); assert.equal(f.store.task(reply.id)!.missionId, 'node-upgrade');
    assert.equal(f.router.getTask(muse, live.id).missionKey, 'node-upgrade');
    const loose = f.submit('no mission'); assert.equal(f.router.getTask(principal(), loose.id).missionKey, loose.id); assert.equal(loose.missionId, null);
    assert.throws(() => f.router.submit(muse, { routeTicket: f.ticket(muse), prompt: 'x', idempotencyKey: 'mission-bad-0001', missionId: 'has space' }), code('INVALID_ARGUMENT'));
    assert.throws(() => f.router.annotate(muse, { kind: 'mission', id: 'node-upgrade', displayName: 'nope' }), code('FORBIDDEN'));
    assert.throws(() => f.router.annotate(principal(), { kind: 'mission', id: 'no-such-mission', displayName: 'x' }), code('NOT_FOUND'));
    assert.throws(() => f.router.annotate(principal(), { kind: 'mission', id: 'node-upgrade', description: 'x' }), code('INVALID_ARGUMENT'));
    f.router.annotate(principal(), { kind: 'mission', id: 'node-upgrade', displayName: '四台機器 Node 升級' });
    assert.equal(f.router.getTask(muse, child.id).missionName, '四台機器 Node 升級'); assert.equal(f.router.getTask(principal(), loose.id).missionName, null); });
test('missions: parts branch a mission; a reply joins the mission it answers; psr_set_mission regroups tasks with their follow-ups', async (t) => { const f = await fixture(); t.after(f.close);
    const muse = principal('muse', { scopes: ['read', 'submit'] }), lab = f.session('lab-test');
    // One goal submitted before missions existed: separate tasks, one with a reply.
    const a = f.submit('inventory gpu', muse), b = f.submit('inventory lab', muse, lab.id), c = f.submit('upgrade gpu', muse);
    const r = f.router.reply(muse, { taskId: b.id, prompt: 'and the services?', idempotencyKey: 'legacy-reply-001' });
    assert.equal(r.missionId, null); assert.equal(f.router.getTask(muse, r.id).missionKey, b.id);
    f.advance(5000);
    const out = f.router.setMission(muse, { taskIds: [a.id, b.id], missionId: 'node-upgrade', missionTitle: 'Node.js 安全升級', missionPart: '盤點' });
    assert.deepEqual(new Set(out.moved), new Set([a.id, b.id, r.id]));
    assert.deepEqual([a, b, r].map(x => [f.router.getTask(muse, x.id).missionKey, f.store.task(x.id)!.missionPart, f.store.task(x.id)!.missionTitle]), Array(3).fill(['node-upgrade', '盤點', 'Node.js 安全升級']));
    assert.equal(f.store.task(r.id)!.updatedAt, r.updatedAt);
    f.router.setMission(muse, { taskIds: [c.id], missionId: 'node-upgrade', missionPart: '升級' });
    const next = f.router.submit(muse, { routeTicket: f.ticket(muse, lab.id), prompt: 'upgrade lab', idempotencyKey: 'part-submit-001', missionId: 'node-upgrade', missionPart: '升級' });
    const follow = f.router.reply(muse, { taskId: next.id, prompt: 'verify', idempotencyKey: 'part-reply-001' });
    assert.deepEqual([next.missionPart, f.store.task(follow.id)!.missionPart, f.store.task(follow.id)!.missionId], ['升級', '升級', 'node-upgrade']);
    f.router.setMission(muse, { taskIds: [c.id], missionId: 'node-upgrade', missionPart: null }); assert.equal(f.store.task(c.id)!.missionPart, null);
    assert.deepEqual(new Set(f.router.setMission(muse, { taskIds: [next.id], missionId: 'lab-upgrade' }).moved), new Set([next.id, follow.id]));
    assert.equal(f.store.task(follow.id)!.missionPart, '升級');
    assert.throws(() => f.router.setMission(principal('grokbot', { scopes: ['read', 'submit'] }), { taskIds: [a.id], missionId: 'mine-now' }), code('FORBIDDEN'));
    f.router.setMission(principal(), { taskIds: [a.id], missionId: 'owner-moved' }); assert.equal(f.store.task(a.id)!.missionId, 'owner-moved');
    for (const bad of [{ taskIds: [], missionId: 'x' }, { taskIds: [a.id], missionId: 'has space' }, { taskIds: [a.id], missionId: 'x', missionPart: ' ' }, { taskIds: [a.id], missionId: 'x', missionPart: 'x'.repeat(41) }])
        assert.throws(() => f.router.setMission(muse, bad), code('INVALID_ARGUMENT'), JSON.stringify(bad));
    assert.throws(() => f.router.setMission(muse, { taskIds: ['task_missing'], missionId: 'x' }), code('NOT_FOUND')); });
test('handoff: remote path is not mistaken for file transfer', async (t) => { const f = await fixture(); t.after(f.close); const a = f.submit(); await assert.rejects(() => f.router.handoff(principal(), { sourceTaskId: a.id, targetRouteTicket: f.ticket(principal(), f.session('lab-test').id), idempotencyKey: 'bad-path-001', objective: 'Read it', contextSummary: 'File is elsewhere', artifactRefs: [{ kind: 'host_path', hostId: 'gpu1', locator: '/tmp/result.csv' }], acceptanceCriteria: [] }), code('ARTIFACT_UNVERIFIED')); assert.equal(f.store.tasks().length, 1); });
