test('topology: all edges have evidence and both endpoint nodes; session IDs are canonical', async (t) => { const f = await fixture(); t.after(f.close); f.submit(); const top = f.router.topology(principal()); const ids = new Set(top.nodes.map(n => n.id)); for (const s of f.sessions())
    assert(ids.has(s.id)); for (const e of top.edges) {
    assert(ids.has(e.source));
    assert(ids.has(e.target));
    assert(e.evidence.recordRef);
} assert(!top.edges.some(e => e.kind === 'native_parent')); });
