test('writer ownership: a task queued behind an unreleased finished task says what it waits for', async (t) => { const f = await fixture(c => c.daemons[0].mappings[0].releasePolicy = 'manual'); t.after(f.close); const first = f.submit(); await f.router.tick(); const second = f.submit('Second instruction'); f.demos.get('gpu-research')!.finish('agent-1'); await f.router.tick(); assert.equal(f.store.task(first.id)!.state, 'completed'); assert.equal(f.store.task(second.id)!.state, 'queued'); assert.match(f.store.task(second.id)!.blocker!, new RegExp(`writer release of finished task ${first.id}: releasePolicy manual`)); });
