test('events: a merged history row replaces live chunks instead of duplicating them', async (t) => { const f = await fixture(); t.after(f.close); const task = f.submit(); await f.router.tick(); const a = f.demos.get('gpu-research')!, turn = f.store.task(task.id)!.turnId; const chunk = a.emit('agent-1', 'assistant_message', turn, 'Hel'); assert.equal(f.store.task(task.id)!.resultSummary, 'Hel'); const seq = Number(chunk.cursor), history = a.history.bind(a); a.history = async (s, c) => [...await history(s, c), { id: 'merged', sessionId: 'agent-1', cursor: String(seq + 1), seqStart: seq, turnId: turn, type: 'assistant_message', text: 'Hello' }]; await f.router.tick(); assert.equal(f.store.task(task.id)!.resultSummary, 'Hello'); a.emit('agent-1', 'assistant_message', turn, 'lo'); assert.equal(f.store.task(task.id)!.resultSummary, 'Hello'); a.finish('agent-1', ' world'); await f.router.tick(); assert.equal(f.store.task(task.id)!.resultSummary, 'Hello world'); assert.equal(f.store.task(task.id)!.state, 'completed'); assert.equal('resultParts' in f.router.getTask(principal(), task.id), false); });
test('events: tasks stored before resultParts keep their earlier result text', async (t) => { const f = await fixture(); t.after(f.close); const task = f.submit(); await f.router.tick(); const { resultParts, ...legacy } = { ...f.store.task(task.id)!, resultSummary: 'earlier ' }; f.store.putTask(legacy); f.demos.get('gpu-research')!.emit('agent-1', 'assistant_message', legacy.turnId, 'later'); assert.equal(f.store.task(task.id)!.resultSummary, 'earlier later'); });
test('wait: psr_wait_task reports a timeout, then resolves when the turn finishes', async (t) => { const f = await fixture(); t.after(f.close); const task = f.submit(); await f.router.tick(); const timed = await f.router.waitTask(principal(), task.id, 20); assert.equal(timed.timedOut, true); assert.equal(timed.task.state, 'running'); const pending = f.router.waitTask(principal(), task.id, 5000); f.demos.get('gpu-research')!.finish('agent-1', 'done'); const done = await pending; assert.equal(done.timedOut, false); assert.equal(done.task.state, 'completed'); assert.equal(done.task.resultSummary, 'done'); await assert.rejects(() => f.router.waitTask(principal(), task.id, 60000), code('INVALID_ARGUMENT')); });
test('wait: a permission request ends the wait because a human must act in Paseo', async (t) => { const f = await fixture(); t.after(f.close); const task = f.submit(); await f.router.tick(); const pending = f.router.waitTask(principal(), task.id, 5000); f.demos.get('gpu-research')!.permission('agent-1'); const r = await pending; assert.equal(r.timedOut, false); assert.equal(r.task.state, 'waiting_permission'); });
test('queue: several senders to one busy session are delivered one turn each in submission order', async (t) => { const f = await fixture(); t.after(f.close); const a = f.demos.get('gpu-research')!; f.submit('first'); await f.router.tick(); ['grokbot', 'dot', 'muse'].forEach((kind, i) => f.submit(`later ${i}`, principal(kind))); await f.router.tick(); assert.equal(a.sends.length, 1); for (let i = 0; i < 3; i++) { a.finish('agent-1'); await f.router.tick(); } assert.deepEqual(a.sends.map(s => s.prompt.split('\n')[1]), ['first', 'later 0', 'later 1', 'later 2']); });
test('queue: a task behind a busy session reports its position and expires unsent after queueTimeoutMs', async (t) => { const f = await fixture(); t.after(f.close); const first = f.submit(); await f.router.tick(); const second = f.router.submit(principal(), { routeTicket: f.ticket(), prompt: 'Second', idempotencyKey: 'queue-expiry-0001', queueTimeoutMs: 1000 }); const third = f.submit('Third'); await f.router.tick(); const view = f.router.getTask(principal(), third.id) as any; assert.deepEqual({ position: view.queue.position, of: view.queue.queuedInDomain, holder: view.queue.lockHolderTaskId, busy: view.queue.targetBusy }, { position: 2, of: 2, holder: first.id, busy: true }); f.advance(1500); await f.router.tick(); assert.equal(f.store.task(second.id)!.state, 'canceled'); assert.match(f.store.task(second.id)!.completionEvidence!, /Queue timeout/); assert.equal((f.router.getTask(principal(), third.id) as any).queue.position, 1); f.demos.get('gpu-research')!.finish('agent-1'); await f.router.tick(); assert.deepEqual(f.demos.get('gpu-research')!.sends.map(s => s.prompt.split('\n')[1]), ['Test instruction', 'Third']); });
