test('agent channel: template creation issues a scoped per-session credential that can only post messages, ask services and use its mission forum', async (t) => { const f = await channelFixture(); t.after(f.close); const { s, channel } = await channelSession(f); assert.equal(channel.url, 'http://127.0.0.1:8787/mcp'); assert.deepEqual(channel.tools, ['psr_post_message', 'psr_ask', 'psr_forum_read', 'psr_forum_post', 'psr_resources', 'psr_take', 'psr_release', 'psr_send_file', 'psr_receive_file']); assert.match(channel.token, /^psra_/); const agent = f.router.agentPrincipal(channel.token); assert.deepEqual({ clientId: agent.clientId, kind: agent.entryKind, scopes: agent.scopes }, { clientId: `agent:${s.id}`, kind: 'agent', scopes: ['report', 'ask', 'forum', 'resource', 'transfer'] }); assert.deepEqual(visibleTools(agent).map(x => x.name), ['psr_post_message', 'psr_ask', 'psr_forum_read', 'psr_forum_post', 'psr_resources', 'psr_take', 'psr_release', 'psr_send_file', 'psr_receive_file']); assert.ok(!visibleTools(principal()).some(x => x.name === 'psr_post_message')); await assert.rejects(() => execute(f.router, agent, 'psr_list_sessions', {}), code('FORBIDDEN')); assert.throws(() => f.router.postMessage(principal(), { text: 'impersonation' }), code('FORBIDDEN')); });
test('agent channel: a mid-turn message reaches the client that assigned the task, and wakes its waits', async (t) => { const f = await channelFixture(); t.after(f.close); const { s, channel } = await channelSession(f); const task = f.submit('Do the work', principal('grokbot'), s.id); await f.router.tick(); assert.equal(f.store.task(task.id)!.state, 'running'); const agent = f.router.agentPrincipal(channel.token); const posted = f.router.postMessage(agent, { text: 'Which color should I use?', kind: 'question' }); assert.deepEqual({ taskId: posted.taskId, to: posted.deliveredTo }, { taskId: task.id, to: 'grokbot' }); const inbox = await f.router.waitMessages(principal('grokbot'), { timeoutMs: 0 }); assert.deepEqual(inbox.messages.map(m => [m.kind, m.text, m.taskId, m.sessionRef]), [['question', 'Which color should I use?', task.id, s.id]]); assert.equal((await f.router.waitMessages(principal('dot'), { timeoutMs: 0 })).messages.length, 0); assert.equal((await f.router.waitMessages(principal('dot'), { timeoutMs: 0, all: true })).messages.length, 1); const pending = f.router.waitTask(principal('grokbot'), task.id, 5000, inbox.next); f.router.postMessage(agent, { text: 'Halfway done', kind: 'progress' }); const woke = await pending; assert.equal(woke.timedOut, false); assert.equal(woke.task.state, 'running'); assert.deepEqual(woke.messages!.map(m => m.text), ['Halfway done']); const later = f.router.waitMessages(principal('grokbot'), { after: woke.messages!.at(-1)!.seq, timeoutMs: 5000 }); f.router.postMessage(agent, { text: 'Result so far: 42', kind: 'result' }); assert.deepEqual((await later).messages.map(m => m.text), ['Result so far: 42']); assert.equal(f.store.task(task.id)!.state, 'running'); });
test('agent channel: messages need a running Router task; credentials can be revoked, expire, and are rate limited', async (t) => { const f = await channelFixture(); t.after(f.close); const { s, channel } = await channelSession(f); const agent = f.router.agentPrincipal(channel.token); assert.throws(() => f.router.postMessage(agent, { text: 'nobody asked' }), code('NO_ACTIVE_TASK')); f.submit('Work', principal('muse'), s.id); await f.router.tick(); for (let i = 0; i < 30; i++) f.router.postMessage(agent, { text: `note ${i}` }); assert.throws(() => f.router.postMessage(agent, { text: 'one too many' }), code('RATE_LIMIT')); assert.throws(() => f.router.postMessage(agent, { text: 'x'.repeat(5000) }), code('INVALID_ARGUMENT')); f.advance(3600001); assert.throws(() => f.router.agentPrincipal(channel.token), code('UNAUTHORIZED')); f.advance(-3600001); assert.throws(() => f.router.revokeAgentChannel(principal('grokbot', { scopes: ['read', 'submit'] }), s.id), code('FORBIDDEN')); f.router.revokeAgentChannel(principal(), s.id); assert.throws(() => f.router.agentPrincipal(channel.token), code('UNAUTHORIZED')); assert.throws(() => f.router.agentPrincipal('psra_forged.payload'), code('UNAUTHORIZED')); });
