test('agent channel (observed): template creation injects the local tool; its calls in the timeline reach the assigning client once', async (t) => { const f = await observedFixture(); t.after(f.close); const s = await f.router.createSession(principal(), { templateId: 'lab-codex', idempotencyKey: 'create-observed-0001' }); const a = f.demos.get('lab-test')!; assert.deepEqual(a.channels.get(s.nativeId), { mode: 'observed', command: 'node', tools: ['psr_post_message'] }); const task = f.submit('Work', principal('grokbot'), s.id); await f.router.tick(); const turn = f.store.task(task.id)!.turnId; a.emit(s.nativeId, 'agent_message', turn, 'English or Chinese?', { kind: 'question', callId: 'call-1' }); a.emit(s.nativeId, 'agent_message', turn, 'English or Chinese?', { kind: 'question', callId: 'call-1' }); a.emit(s.nativeId, 'agent_message', 'some-other-turn', 'not ours', { kind: 'note', callId: 'call-2' }); await f.router.tick(); const inbox = await f.router.waitMessages(principal('grokbot'), { timeoutMs: 0 }); assert.deepEqual(inbox.messages.map(m => [m.kind, m.text, m.taskId, m.toClientId]), [['question', 'English or Chinese?', task.id, 'grokbot']]); assert.equal(f.store.task(task.id)!.state, 'running'); });
