test('agent channel: a session keeps the channel it was created with when its daemon changes mode, delivered once either way', async (t) => {
    const f = await observedFixture(); t.after(f.close);
    const lab = f.config.daemons.find(d => d.id === 'lab-test')!, a = f.demos.get('lab-test')!;
    const old = await f.router.createSession(principal(), { templateId: 'lab-codex', idempotencyKey: 'create-observed-0003' });
    lab.agentChannel = { url: 'http://127.0.0.1:8787/mcp' };
    const fresh = await f.router.createSession(principal(), { templateId: 'lab-codex', idempotencyKey: 'create-http-0003' });
    const channel = a.channels.get(fresh.nativeId); assert(channel?.mode === 'http');
    const texts = async (taskId: string) => (await f.router.waitMessages(principal('grokbot'), { timeoutMs: 0, taskId, all: true })).messages.map(m => m.text);
    // one turn of each session; the stub's call shows in the timeline (twice, and once from another turn), an http call as well
    const turn = async (s: { id: string; nativeId: string }, post: boolean) => {
        const task = f.submit('Work', principal('grokbot'), s.id); await f.router.tick();
        const id = f.store.task(task.id)!.turnId;
        if (post) f.router.postMessage(f.router.agentPrincipal(channel.token), { text: 'over http', kind: 'note' });
        a.emit(s.nativeId, 'agent_message', id, 'in the timeline', { kind: 'note', callId: `call-${task.id}` });
        a.emit(s.nativeId, 'agent_message', id, 'in the timeline', { kind: 'note', callId: `call-${task.id}` });
        a.emit(s.nativeId, 'agent_message', 'some-other-turn', 'not ours', { kind: 'note', callId: `other-${task.id}` });
        await f.router.tick(); const got = await texts(task.id);
        a.finish(s.nativeId, 'done'); await f.router.tick();
        return got;
    };
    assert.deepEqual(await turn(old, false), ['in the timeline']); // made on observed, its daemon now http: still read
    assert.deepEqual(await turn(fresh, true), ['over http']); // made on http: the timeline copy is not delivered again
    lab.agentChannel = { mode: 'observed' };
    assert.deepEqual(await turn(fresh, true), ['over http']); // back on observed: still only once
    assert.deepEqual(await turn(old, false), ['in the timeline']);
    // a session the Router did not create (no record) follows its daemon's mode, as before
    assert.deepEqual(await turn(f.session('lab-test'), false), ['in the timeline']);
});

test('agent channel: the first start stamps older creation records with the channel of that start, once, keeping their age', async (t) => {
    const f = await fixture(c => { c.daemons.find(d => d.id === 'lab-test')!.agentChannel = { mode: 'observed' }; c.daemons.find(d => d.id === 'gpu-research')!.agentChannel = { url: 'http://127.0.0.1:8787/mcp' }; c.templates.push({ id: 'gpu-codex', daemonId: 'gpu-research', cwd: '/srv/hft-queue', provider: 'codex/demo', title: 'Queue helper' }); }); t.after(f.close);
    const observed = await f.router.createSession(principal(), { templateId: 'lab-codex', idempotencyKey: 'create-observed-0004' });
    const http = await f.router.createSession(principal(), { templateId: 'gpu-codex', idempotencyKey: 'create-http-0004' });
    const lost = await f.router.createSession(principal(), { templateId: 'lab-codex', idempotencyKey: 'create-observed-0005' });
    const token = f.demos.get('gpu-research')!.channels.get(http.nativeId); assert(token?.mode === 'http');
    f.router.revokeAgentChannel(principal(), http.id);
    type Rec = { sessionRef?: string; templateId?: string; channel?: string; tools?: string[]; tokenExp?: number; channelRevoked?: boolean; updatedAt: number };
    const rec = (ref: string) => f.store.rows<Rec>('creation').find(r => r.data.sessionRef === ref)!;
    const strip = (ref: string, change: Partial<Rec> = {}) => { const r = rec(ref), { channel, tools, tokenExp, ...old } = r.data; f.store.put('creation', r.id, { ...old, ...change }, r.projectId, r.hostId, f.now()); };
    assert.deepEqual([rec(observed.id).data.channel, rec(http.id).data.channel], ['observed', 'http']);
    // records written before channel was kept: no channel, and an http one from before tools were kept, too; one whose session
    // row and template are gone cannot be placed at that start
    strip(observed.id); strip(http.id); strip(lost.id, { templateId: 'gone' }); f.store.remove('session', lost.id, f.now());
    f.store.setMeta('creationChannelBackfill', '');
    const ages = [rec(observed.id).data.updatedAt, rec(http.id).data.updatedAt];
    f.advance(60000);
    const restart = () => new Router(f.config, f.store, f.adapters, f.now);
    const first = restart();
    assert.deepEqual([rec(observed.id).data.channel, rec(http.id).data.channel, rec(lost.id).data.channel], ['observed', 'http', undefined]);
    assert.deepEqual([rec(observed.id).data.updatedAt, rec(http.id).data.updatedAt], ages);
    assert.equal(rec(http.id).data.channelRevoked, true); assert.throws(() => first.agentPrincipal(token.token), code('UNAUTHORIZED'));
    assert.deepEqual(JSON.parse(f.store.meta('creationChannelBackfill')!).modes, { 'gpu-research': 'http', 'gpu-review': null, 'dev-app': null, 'lab-test': 'observed' });
    // a later start after lab-test moved to http stamps nothing, even a record it could place now
    strip(lost.id, { templateId: 'lab-codex' });
    f.config.daemons.find(d => d.id === 'lab-test')!.agentChannel = { url: 'http://127.0.0.1:8787/mcp' };
    restart();
    assert.deepEqual([rec(observed.id).data.channel, rec(lost.id).data.channel], ['observed', undefined]);
});

