test('annotations: the owner names hosts, sessions and templates; everyone reads them; only admin writes', async (t) => { const f = await fixture(c => { c.hosts[0].description = 'GPU research box'; c.hosts[0].rules = ['No live orders']; c.templates[0].description = 'Backtest companion in the lab'; }); t.after(f.close); const { sessions: _n, localSessions: _l, routerHere: _r, machine: _m, logins: _g, ...gpu1 } = f.router.listHosts(principal('muse')).hosts.find(h => h.id === 'gpu1')!; assert.deepEqual(gpu1, { id: 'gpu1', label: 'GPU · Research', configLabel: 'GPU · Research', description: 'GPU research box', tags: [], rules: ['No live orders'], ownerApprovalOnly: false }); f.router.annotate(principal(), { kind: 'host', id: 'gpu1', displayName: 'Data lake', tags: ['data'], description: null }); const h = f.router.listHosts(principal('muse')).hosts.find(h => h.id === 'gpu1')!; assert.deepEqual([h.label, h.description, h.tags, h.rules], ['Data lake', null, ['data'], ['No live orders']]); const s = f.session(); f.router.annotate(principal(), { kind: 'session', id: s.id, displayName: 'Maker-fill lab', description: 'Owns the fill study' }); assert.deepEqual([f.session().displayName, f.session().description], ['Maker-fill lab', 'Owns the fill study']); f.router.annotate(principal(), { kind: 'template', id: 'lab-codex', displayName: 'Backtester' }); assert.deepEqual(f.router.listTemplates(principal('muse')).templates.map(t => [t.id, t.title, t.description, t.hostId]), [['lab-codex', 'Backtester', 'Backtest companion in the lab', 'lab3']]); assert.throws(() => f.router.annotate(principal('muse', { scopes: ['read', 'submit'] }), { kind: 'host', id: 'gpu1', displayName: 'x' }), code('FORBIDDEN')); assert.throws(() => f.router.annotate(principal(), { kind: 'host', id: 'nope', displayName: 'x' }), code('NOT_FOUND')); assert.throws(() => f.router.annotate(principal(), { kind: 'template', id: 'lab-codex', rules: ['x'] }), code('INVALID_ARGUMENT')); assert.throws(() => f.router.annotate(principal(), { kind: 'host', id: 'gpu1', displayName: 'x'.repeat(81) }), code('INVALID_ARGUMENT')); });
